from langflow.custom import CustomComponent
from langflow.io import MessageTextInput, Output
from langflow.schema import Data
import json
import re

class IntentClassifier(CustomComponent):
    display_name = "Intent Classifier"
    description = "Classifies user intent and routes accordingly"

    def build_config(self):
        return {
            "user_message": {
                "display_name": "User Message",
                "field_type": "str",
            },
            "order_state": {
                "display_name": "Order State",
                "field_type": "str",
                "value": "{}"
            }
        }

    def build(
        self,
        user_message: str,
        order_state: str = "{}"
    ) -> Data:
        message_lower = user_message.lower()

        # Intent patterns
        menu_keywords = ['menu', 'what do you have', 'options', 'food', 'drink', 'serve', 'available']
        order_keywords = ['order', 'want', 'like', 'get', 'add', 'remove', 'cancel', 'change']

        intent = 'general'

        if any(keyword in message_lower for keyword in menu_keywords):
            intent = 'menu_inquiry'
        elif any(keyword in message_lower for keyword in order_keywords):
            intent = 'order_management'

        # Parse current order state
        try:
            order_dict = json.loads(order_state) if order_state else {}
        except:
            order_dict = {}

        result = {
            "intent": intent,
            "user_message": user_message,
            "order_state": json.dumps(order_dict)
        }

        self.status = f"Intent: {intent}"
        return Data(data=result)

from langflow.custom import CustomComponent
from langflow.io import MessageTextInput, Output
from langflow.schema import Data
import json
import re

class OrderManager(CustomComponent):
    display_name = "Order Manager"
    description = "Manages order state (add/remove items)"

    def build_config(self):
        return {
            "user_message": {
                "display_name": "User Message",
                "field_type": "str",
            },
            "order_state": {
                "display_name": "Current Order State",
                "field_type": "str",
                "value": "{}"
            }
        }

    def build(
        self,
        user_message: str,
        order_state: str = "{}"
    ) -> Data:
        # Parse current order
        try:
            order_dict = json.loads(order_state) if order_state else {}
        except:
            order_dict = {}

        message_lower = user_message.lower()
        response = ""

        # Extract items and quantities
        add_patterns = r'(?:add|order|want|get)\s+(?:(\d+)\s+)?([\w\s]+?)(?:\s+to|\s+please|$)'
        remove_patterns = r'(?:remove|cancel|delete)\s+(?:(\d+)\s+)?([\w\s]+?)(?:\s+from|\s+please|$)'

        # Process additions
        for match in re.finditer(add_patterns, message_lower):
            quantity = int(match.group(1)) if match.group(1) else 1
            item = match.group(2).strip()

            if item in order_dict:
                order_dict[item] += quantity
            else:
                order_dict[item] = quantity

            response += f"Added {quantity} {item} to your order. "

        # Process removals
        for match in re.finditer(remove_patterns, message_lower):
            quantity = int(match.group(1)) if match.group(1) else None
            item = match.group(2).strip()

            if item in order_dict:
                if quantity:
                    order_dict[item] = max(0, order_dict[item] - quantity)
                    if order_dict[item] == 0:
                        del order_dict[item]
                else:
                    del order_dict[item]
                response += f"Removed {item} from your order. "

        # Generate order summary
        if order_dict:
            summary = "Your current order includes "
            items = [f"{qty} {item}" for item, qty in order_dict.items()]
            if len(items) == 1:
                summary += items[0]
            elif len(items) == 2:
                summary += f"{items[0]} and {items[1]}"
            else:
                summary += ", ".join(items[:-1]) + f" and {items[-1]}"
            response += summary + "."
        else:
            response += "Your order is currently empty."

        result = {
            "response": response,
            "order_state": json.dumps(order_dict)
        }

        return Data(data=result)
